// Matchday Call partner report. Plain JS, no build step.
// Data comes from window.SIM (data/data.js, generated by sim/simulate.js).
// URL options: ?autoplay=1  &seconds=16 (replay length)  &demo=0 (hide the "Simulated data" tag)
(function () {
  "use strict";
  var SIM = window.SIM;
  var params = new URLSearchParams(location.search);
  var REPLAY_SECONDS = Number(params.get("seconds")) || 16;
  if (params.get("demo") === "0") document.getElementById("demo-tag").hidden = true;

  // ---- timeline: 0..45 first half, 46..48 half-time, 49..97 second half, 98..117 after full time
  var T = [], m, i;
  for (m = 0; m <= 45; m++) T.push({ phase: "1H", clock: m === 0 ? "kick-off" : m + "'" });
  for (i = 0; i < 3; i++) T.push({ phase: "HT", clock: "half-time" });
  for (m = 46; m <= 94; m++) T.push({ phase: "2H", clock: m > 90 ? "90+" + (m - 90) + "'" : m + "'" });
  for (i = 1; i <= 20; i++) T.push({ phase: "POST", clock: "FT +" + i + " min" });
  var N = T.length, FT = 97, s = SIM.series;
  var goals = [{ i: 18, label: "Goal ARS 18'" }, { i: 57, label: "Goal CHE 54'" }, { i: 80, label: "Goal ARS 77'" }];

  var cum = { su: [], pl: [], sc: [], calls: [] }, a = 0, b = 0, c = 0, d = 0;
  for (i = 0; i < N; i++) {
    a += s.signups[i]; b += s.started[i]; c += s.scans[i]; d += s.calls[i];
    cum.su.push(a); cum.pl.push(b); cum.sc.push(c); cum.calls.push(d);
  }
  var avgLift = goals.reduce(function (x, g) {
    return x + s.calls[g.i] / ((s.calls[g.i - 3] + s.calls[g.i - 2] + s.calls[g.i - 1]) / 3) / goals.length;
  }, 0);

  function fmt(n) { return Math.round(n).toLocaleString("en-US"); }
  function pct(x, y, dp) { return y > 0 ? (x / y * 100).toFixed(dp == null ? 1 : dp) + "%" : "—"; }
  function $(id) { return document.getElementById(id); }
  function setText(id, v) { $(id).textContent = v; }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function barCell(widthPct, color, label) {
    var wrap = el("div", "barcell"), bar = el("div", "bar"), fill = el("span");
    fill.style.width = widthPct; fill.style.background = color;
    bar.appendChild(fill); wrap.appendChild(bar); wrap.appendChild(el("span", "barnum", label));
    return wrap;
  }

  // ---- static: findings, funnel, channels
  var F = SIM.funnel;
  setText("new-share", Math.round(SIM.newShare * 100) + "%");
  setText("i-ht", pct(F.htSignups, F.signedUp, 0));
  setText("i-ht-left", fmt(F.htSignedLeftEarly));
  setText("i-post", pct(F.ftSignups, F.signedUp, 0));
  setText("i-goal", "×" + avgLift.toFixed(1));

  var steps = [
    ["Scanned the QR code", F.scanned], ["Started a game", F.started], ["Made at least one call", F.called],
    ["Made a forecast", F.forecast], ["Saw a sign-up prompt", F.sawPrompt], ["Signed up with email", F.signedUp]
  ];
  var fBody = $("funnel").tBodies[0];
  steps.forEach(function (st, j) {
    var last = j === steps.length - 1, tr = el("tr", last ? "goal" : null);
    tr.appendChild(el("td", null, st[0]));
    var td = el("td"); td.appendChild(barCell((st[1] / F.scanned * 100).toFixed(1) + "%", last ? "var(--green)" : "var(--purple-soft)", fmt(st[1]))); tr.appendChild(td);
    tr.appendChild(el("td", "r muted", pct(st[1], F.scanned)));
    tr.appendChild(el("td", "r muted", j === 0 ? "—" : pct(st[1], steps[j - 1][1])));
    fBody.appendChild(tr);
  });

  var ch = SIM.channels.slice().sort(function (x, y) { return y[2] / y[1] - x[2] / x[1]; });
  var maxRate = ch[0][2] / ch[0][1], totS = 0, totU = 0, cBody = $("channel-table").tBodies[0];
  ch.forEach(function (x) {
    totS += x[1]; totU += x[2];
    var tr = el("tr");
    tr.appendChild(el("td", null, x[0]));
    tr.appendChild(el("td", "r muted", fmt(x[1])));
    tr.appendChild(el("td", "r muted", fmt(x[2])));
    var td = el("td"); td.appendChild(barCell((x[2] / x[1] / maxRate * 100).toFixed(1) + "%", "var(--purple)", pct(x[2], x[1]))); tr.appendChild(td);
    cBody.appendChild(tr);
  });
  setText("ch-scans", fmt(totS)); setText("ch-signups", fmt(totU)); setText("ch-rate", pct(totU, totS));
  var room = SIM.channels[0], walk = SIM.channels.slice(1).reduce(function (acc, x) { return [acc[0] + x[1], acc[1] + x[2]]; }, [0, 0]);
  setText("i-room", "×" + ((room[2] / room[1]) / (walk[1] / walk[0])).toFixed(1));

  // ---- charts
  var NS = "http://www.w3.org/2000/svg";
  var X0 = 48, X1 = 1180, STEP = (X1 - X0) / N, BW = STEP * 0.66;
  function xAt(k) { return X0 + (k + 0.5) * STEP; }
  function bnd(k) { return X0 + k * STEP; }
  function add(svg, tag, attrs, style, text) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (style) e.setAttribute("style", style);
    if (text != null) e.textContent = text;
    svg.appendChild(e); return e;
  }
  function bands(svg, top, bottom) {
    add(svg, "rect", { x: bnd(46), y: top, width: 3 * STEP, height: bottom - top }, "fill: #F4F1F6");
    add(svg, "rect", { x: bnd(FT + 1), y: top, width: X1 - bnd(FT + 1), height: bottom - top }, "fill: #F2FAF6");
  }
  function grid(svg, ys, base) {
    ys.forEach(function (y) { add(svg, "line", { x1: X0, x2: X1, y1: y, y2: y }, "stroke: " + (y === base ? "#CFC5D4" : "#EEEAF1") + "; stroke-width: 1"); });
  }

  // chart A: players online / calls per minute
  var A = $("chart-a"), AT = 24, AB = 200;
  bands(A, AT, AB);
  grid(A, [200, 156, 112, 68, 24], AB);
  var aTicks = [156, 112, 68, 24].map(function (y) { return add(A, "text", { x: 40, y: y + 4 }, "text-anchor: end", ""); });
  add(A, "text", { x: 40, y: 204 }, "text-anchor: end", "0");
  var aFut = add(A, "path", {}, "fill: #E7E0EA");
  var aPast = add(A, "path", {}, "fill: #8C6F96");
  var aArea = add(A, "path", {}, "fill: rgba(55,0,60,0.08)");
  var aLine = add(A, "polyline", {}, "fill: none; stroke: #37003C; stroke-width: 2; stroke-linejoin: round");
  goals.forEach(function (g) {
    add(A, "line", { x1: xAt(g.i), x2: xAt(g.i), y1: 18, y2: AB }, "stroke: #E90052; stroke-width: 1");
    add(A, "text", { x: xAt(g.i) + 4, y: 14 }, "font-weight: 600; fill: #C20045", g.label);
  });
  add(A, "text", { x: bnd(47.5), y: 14 }, "text-anchor: middle; font-weight: 600", "HT");
  add(A, "line", { x1: bnd(FT + 1), x2: bnd(FT + 1), y1: 18, y2: AB }, "stroke: #37003C; stroke-width: 1");
  add(A, "text", { x: bnd(FT + 1) + 4, y: 14 }, "font-weight: 600; fill: #37003C", "Full time");
  var aPlay = add(A, "line", { y1: AT, y2: AB }, "stroke: #1F0A24; stroke-width: 1; stroke-dasharray: 3 3");

  // chart B: sign-ups per minute
  var B = $("chart-b"), BT = 12, BB = 140;
  bands(B, BT, BB);
  grid(B, [140, 76, 12], BB);
  [[144, "0"], [80, "500"], [16, "1,000"]].forEach(function (t) { add(B, "text", { x: 40, y: t[0] }, "text-anchor: end", t[1]); });
  goals.forEach(function (g) { add(B, "line", { x1: xAt(g.i), x2: xAt(g.i), y1: BT, y2: BB }, "stroke: #F6B8CE; stroke-width: 1"); });
  add(B, "line", { x1: bnd(FT + 1), x2: bnd(FT + 1), y1: BT, y2: BB }, "stroke: #37003C; stroke-width: 1");
  add(B, "text", { x: bnd(49) + 6, y: 28 }, "font-weight: 600; fill: #006B3D", "Half-time window");
  add(B, "text", { x: bnd(FT + 1) + 6, y: 28 }, "font-weight: 600; fill: #006B3D", "Full-time screen");
  var bFut = add(B, "path", {}, "fill: #D7F0E3");
  var bPast = add(B, "path", {}, "fill: #00A85A");
  var bPlay = add(B, "line", { y1: BT, y2: BB }, "stroke: #1F0A24; stroke-width: 1; stroke-dasharray: 3 3");
  [[0, "KO"], [15, "15'"], [30, "30'"], [63, "60'"], [78, "75'"], [107, "+10 min"]].forEach(function (t) {
    add(B, "text", { x: xAt(t[0]), y: 162 }, "text-anchor: middle", t[1]);
  });
  add(B, "text", { x: bnd(47.5), y: 162 }, "text-anchor: middle", "HT");
  add(B, "text", { x: bnd(FT + 1), y: 162 }, "text-anchor: middle; font-weight: 600; fill: #37003C", "FT");
  add(B, "text", { x: X1, y: 162 }, "text-anchor: end", "+20 min");

  // ---- state + render
  var idx = N - 1, timer = null, hold = 0, metric = "players";
  var holds = {}; goals.forEach(function (g) { holds[g.i] = 8; }); holds[46] = 5; holds[FT] = 10;

  function bar(k, y, base) {
    var x = xAt(k) - BW / 2;
    return "M" + x.toFixed(1) + " " + base + "V" + y.toFixed(1) + "H" + (x + BW).toFixed(1) + "V" + base + "Z";
  }

  function render() {
    var aMax = metric === "players" ? 8000 : 12000, k;
    function yA(v) { return AB - v / aMax * (AB - AT); }
    function yB(v) { return BB - Math.min(v, 1000) / 1000 * (BB - BT); }
    var ap = "", af = "", bp = "", bf = "", pts = [];
    for (k = 0; k < N; k++) {
      if (metric === "calls" && s.calls[k] > 0) { if (k <= idx) ap += bar(k, yA(s.calls[k]), AB); else af += bar(k, yA(s.calls[k]), AB); }
      if (s.signups[k] > 0) { if (k <= idx) bp += bar(k, yB(s.signups[k]), BB); else bf += bar(k, yB(s.signups[k]), BB); }
      if (metric === "players" && k <= idx) pts.push(xAt(k).toFixed(1) + "," + yA(s.live[k]).toFixed(1));
    }
    aPast.setAttribute("d", ap); aFut.setAttribute("d", af); bPast.setAttribute("d", bp); bFut.setAttribute("d", bf);
    aLine.setAttribute("points", pts.join(" "));
    aArea.setAttribute("d", pts.length ? "M" + xAt(0).toFixed(1) + "," + AB + " L" + pts.join(" L") + " L" + xAt(idx).toFixed(1) + "," + AB + " Z" : "");
    var ticks = metric === "players" ? ["2K", "4K", "6K", "8K"] : ["3K", "6K", "9K", "12K"];
    aTicks.forEach(function (t, j) { t.textContent = ticks[j]; });
    A.setAttribute("aria-label", (metric === "players" ? "Players online" : "Calls per minute") + " across the match, with goals, half-time and full time marked");

    var atEnd = idx >= N - 1 && !timer, px = xAt(idx);
    [aPlay, bPlay].forEach(function (l) { l.setAttribute("x1", px); l.setAttribute("x2", px); l.style.opacity = atEnd ? 0 : 0.6; });

    var peak = 0, peakI = 0;
    for (k = 0; k <= idx; k++) if (s.live[k] > peak) { peak = s.live[k]; peakI = k; }
    var players = cum.pl[idx], scans = cum.sc[idx], su = cum.su[idx];
    setText("clock", atEnd ? "FT +20 min (final)" : T[idx].clock);
    setText("k-scans", fmt(scans)); setText("k-players", fmt(players)); setText("k-playrate", pct(players, scans));
    setText("k-peak", fmt(peak)); setText("k-peakclock", T[peakI].clock);
    setText("k-calls", fmt(cum.calls[idx])); setText("k-perplayer", players > 0 ? (cum.calls[idx] / players).toFixed(1) : "0");
    setText("k-signups", fmt(su)); setText("k-conv", pct(su, players));
    setText("readout", "At " + T[idx].clock + ": " + fmt(s.live[idx]) + " players online · " + fmt(s.calls[idx]) + " calls per minute");
    setText("wave-note", fmt(cum.su[Math.min(idx, 48)] - cum.su[45]) + " at half-time · " + fmt(Math.max(0, su - cum.su[FT])) + " after full time");

    $("seg-players").setAttribute("aria-pressed", metric === "players");
    $("seg-calls").setAttribute("aria-pressed", metric === "calls");
    $("icon-play").style.display = timer ? "none" : "";
    $("icon-pause").style.display = timer ? "" : "none";
    setText("play-label", timer ? "Pause" : (idx >= N - 1 ? "Replay match" : "Resume"));
  }

  function stop() { if (timer) { clearInterval(timer); timer = null; } render(); }
  function play() {
    if (timer) return;
    if (idx >= N - 1) idx = 0;
    hold = 0;
    var ms = Math.max(25, Math.round(REPLAY_SECONDS * 1000 / (N + 31)));
    timer = setInterval(function () {
      if (hold > 0) { hold--; return; }
      if (idx + 1 >= N - 1) { idx = N - 1; stop(); return; }
      idx++; if (holds[idx]) hold = holds[idx];
      render();
    }, ms);
    render();
  }
  $("play").addEventListener("click", function () { if (timer) stop(); else play(); });
  $("seg-players").addEventListener("click", function () { metric = "players"; render(); });
  $("seg-calls").addEventListener("click", function () { metric = "calls"; render(); });

  render();
  if (params.get("autoplay") === "1") play();
})();
